// Order generator — see specs/shared/n8n-workflows.md §3.
// Reads catalogue (cached), composes 1-N valid orders (single currency per
// order), engineers ~COMPENSATION_RATIO of them to total .99 (R42), places
// them via POST /orders, and returns a per-order run log.

const gatewayUrl = ($env.OTC_GATEWAY_URL || 'http://gateway:3001').replace(/\/$/, '');
const username = $env.GATEWAY_OPERATOR_USERNAME;
const password = $env.GATEWAY_OPERATOR_PASSWORD;
const timeoutMs = Number($env.OTC_REQUEST_TIMEOUT_MS || 10000);

const enabled = ($env.ORDER_GENERATOR_ENABLED ?? 'true') !== 'false';
const ordersPerRun = Number($env.ORDER_GENERATOR_ORDERS_PER_RUN || 1);
const compensationRatio = Number($env.ORDER_GENERATOR_COMPENSATION_RATIO ?? 0.15);
const maxLines = Number($env.ORDER_GENERATOR_MAX_LINES || 4);
const maxUnits = Number($env.ORDER_GENERATOR_MAX_UNITS || 10);
const retailerFilter = ($env.ORDER_GENERATOR_RETAILERS || '').split(',').map((s) => s.trim()).filter(Boolean);
const companyFilter = ($env.ORDER_GENERATOR_COMPANIES || '').split(',').map((s) => s.trim()).filter(Boolean);
const catalogTtlMs = Number($env.ORDER_GENERATOR_CATALOG_TTL_SECONDS || 600) * 1000;

if (!enabled) {
  return [{ json: { skipped: true, reason: 'ORDER_GENERATOR_ENABLED=false' } }];
}

// ── small helpers ──────────────────────────────────────────────────────
function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function requestWithRetry(options, { retryOn5xxAndNetwork = true } = {}) {
  const attempts = retryOn5xxAndNetwork ? 4 : 1; // 1 try + up to 3 retries
  let lastErr;
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      return await this.helpers.httpRequest({ timeout: timeoutMs, ...options });
    } catch (err) {
      lastErr = err;
      const status = err.status ?? err.response?.status;
      const isNetworkError = status === undefined;
      const is5xx = typeof status === 'number' && status >= 500;
      if (!retryOn5xxAndNetwork || !(isNetworkError || is5xx) || attempt === attempts - 1) {
        throw err;
      }
      await sleep(2 ** attempt * 250); // exponential backoff: 250, 500, 1000ms
    }
  }
  throw lastErr;
}

async function login() {
  const res = await requestWithRetry.call(this, {
    method: 'POST',
    url: `${gatewayUrl}/auth/login`,
    body: { username, password },
    json: true,
  });
  return res.accessToken;
}

function authHeaders(token) {
  return { Authorization: `Bearer ${token}` };
}

// ── catalogue, cached in workflow static data for CATALOG_TTL_SECONDS ───
async function loadCatalogue(token) {
  const staticData = $getWorkflowStaticData('global');
  const now = Date.now();
  if (staticData.catalogueAt && now - staticData.catalogueAt < catalogTtlMs && staticData.products) {
    return { products: staticData.products, retailers: staticData.retailers, companies: staticData.companies };
  }
  const headers = authHeaders(token);
  const [productsRes, retailersRes, companiesRes] = await Promise.all([
    requestWithRetry.call(this, { method: 'GET', url: `${gatewayUrl}/catalog/products`, headers, json: true }),
    requestWithRetry.call(this, { method: 'GET', url: `${gatewayUrl}/catalog/retailers`, headers, json: true }),
    requestWithRetry.call(this, { method: 'GET', url: `${gatewayUrl}/catalog/companies`, headers, json: true }),
  ]);
  const products = productsRes.items.filter((p) => p.enabled);
  const retailers = retailersRes.items.filter((r) => r.enabled);
  const companies = companiesRes.items.filter((c) => c.enabled);
  staticData.products = products;
  staticData.retailers = retailers;
  staticData.companies = companies;
  staticData.catalogueAt = now;
  return { products, retailers, companies };
}

function pick(arr) {
  return arr[Math.floor(Math.random() * arr.length)];
}

// ── order composition (§3.1) ─────────────────────────────────────────
function composeOrder(catalogue) {
  const retailers = retailerFilter.length
    ? catalogue.retailers.filter((r) => retailerFilter.includes(r.code))
    : catalogue.retailers;
  const companies = companyFilter.length
    ? catalogue.companies.filter((c) => companyFilter.includes(c.code))
    : catalogue.companies;
  if (!retailers.length || !companies.length) return null;

  const retailer = pick(retailers);
  const company = pick(companies);
  const currency = retailer.currency;
  const eligibleProducts = catalogue.products.filter((p) => p.currency === currency);
  if (!eligibleProducts.length) return null;

  const lineCount = 1 + Math.floor(Math.random() * Math.max(1, maxLines));
  const chosen = [];
  for (let i = 0; i < lineCount; i += 1) chosen.push(pick(eligibleProducts));

  const lines = chosen.map((p) => ({
    productCode: p.code,
    quantity: 1 + Math.floor(Math.random() * Math.max(1, maxUnits)),
    unitPrice: p.price,
  }));

  return { retailerCode: retailer.code, companyCode: company.code, currency, lines, notes: 'n8n order generator' };
}

// ── §3.2 the .99 engineering ──────────────────────────────────────────
function orderTotal(order) {
  return order.lines.reduce((sum, l) => sum + l.unitPrice * l.quantity, 0);
}

function mod100(n) {
  return ((n % 100) + 100) % 100;
}

// Tries to nudge the LAST line's unitPrice so the order total ends in .99.
// Returns true on success (order mutated in place), false on a genuine miss
// (kept as an ordinary order, per §3.2's "counts a miss").
function engineerCompensation(order) {
  // Review fix (D1): the previous version adjusted only the last line's
  // unitPrice and left its quantity untouched, so the reachable mod-100
  // residues were the subgroup generated by gcd(quantity, 100) — measured
  // at ~50% hit rate over 200,000 compositions (progress/impl_n8n_workflows.md,
  // "Review fixes"). Forcing the engineered line's quantity to 1 makes
  // gcd(1, 100) = 1, so every residue 0..99 is reachable by adding a
  // non-negative delta to unitPrice alone — 100% hit rate, still inside
  // §3.2's "at most 99 minor units spread over one line" budget, and the
  // adjustment is always an INCREASE so it can never drive a price negative.
  const lastLine = order.lines[order.lines.length - 1];
  lastLine.quantity = 1;
  const total = orderTotal(order);
  const currentMod = mod100(total);
  if (currentMod === 99) return true;
  const delta = mod100(99 - total); // 0..99, always reachable at quantity 1
  if (lastLine.unitPrice + delta < 1) return false; // defensive; unreachable with delta >= 0
  lastLine.unitPrice += delta;
  return mod100(orderTotal(order)) === 99;
}

// ── placement ───────────────────────────────────────────────────────
async function placeOrder(token, order) {
  try {
    const res = await requestWithRetry.call(this, {
      method: 'POST',
      url: `${gatewayUrl}/orders`,
      headers: authHeaders(token),
      body: order,
      json: true,
    });
    return { outcome: 'accepted', orderId: res.orderId, orderReference: res.orderReference, totalAmount: res.initialAmount, currency: res.currency };
  } catch (err) {
    const status = err.status ?? err.response?.status;
    if (status === 409 || status === 422) {
      return { outcome: 'refused', status };
    }
    if (status === 401) {
      // single re-login + one retry, per §2.1
      const freshToken = await login.call(this);
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: `${gatewayUrl}/orders`,
        headers: authHeaders(freshToken),
        body: order,
        json: true,
        timeout: timeoutMs,
      });
      return { outcome: 'accepted', orderId: res.orderId, orderReference: res.orderReference, totalAmount: res.initialAmount, currency: res.currency };
    }
    throw err;
  }
}

// ── main ────────────────────────────────────────────────────────────
async function run() {
  const token = await login.call(this);
  const catalogue = await loadCatalogue.call(this, token);
  const results = [];
  for (let i = 0; i < Math.max(1, ordersPerRun); i += 1) {
    const order = composeOrder(catalogue);
    if (!order) {
      results.push({ outcome: 'skipped', reason: 'no eligible retailer/company/product combination' });
      continue;
    }
    let compensating = false;
    if (compensationRatio > 0 && Math.random() < compensationRatio) {
      compensating = engineerCompensation(order);
    }
    try {
      const placed = await placeOrder.call(this, token, order);
      results.push({ ...placed, compensationEngineered: compensating, retailerCode: order.retailerCode, companyCode: order.companyCode });
    } catch (err) {
      results.push({ outcome: 'error', message: err.message, status: err.status ?? err.response?.status });
    }
  }
  return results;
}

const runResults = await run.call(this);
return runResults.map((r) => ({ json: r }));
